1	/* IFTO-HOME — INFOTOOLS Dashboard for Obsidian */
2	
3	.ifto-settings-root {
4	  box-sizing: border-box !important;
5	  width: 100% !important;
6	  max-width: 960px !important;
7	  margin: 0 auto !important;
8	  padding: 24px clamp(24px, 5vw, 48px) !important;
9	}
10	
11	.ifto-container {
12	  /* New design tokens (widget refresh — Timespot / Crypto / Dribbble mix) */
13	  --ifto-card-bg: #ffffff;
14	  --ifto-text:    #111111;
15	  --ifto-text-2:  #6b7280;
16	  --ifto-text-3:  #9ca3af;
17	  --ifto-divider: #e5e7eb;
18	  --ifto-accent:  #000000;
19	  --ifto-accent-text: #ffffff;
20	
21	  --ifto-fs-hero: 56px;
22	  --ifto-fs-xl:   32px;
23	  --ifto-fs-lg:   18px;
24	  --ifto-fs-base: 14px;
25	  --ifto-fs-sm:   12px;
26	
27	  --ifto-card-pad: 24px;
28	  --ifto-card-gap: 16px;
29	
30	  --ifto-shadow: 0 1px 3px rgba(0,0,0,.04), 0 4px 12px rgba(0,0,0,.06);
31	  --ifto-shadow-strong: 0 4px 16px rgba(0,0,0,.10);
32	
33	  /* Legacy tokens (kept for non-widget classes like header / nav) */
34	  --ifto-gray-1: #333333;
35	  --ifto-gray-4: #bdbdbd;
36	  --ifto-gray-5: #e0e0e0;
37	  --ifto-gray-6: #f2f2f2;
38	  --ifto-bg: #ffffff;
39	  --ifto-font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
40	  --ifto-section-x: 127px;
41	}
42	
43	.theme-light .ifto-container,
44	body.theme-light .ifto-container {
45	  --ifto-card-bg: #ffffff;
46	  --ifto-text:    #111111;
47	  --ifto-text-2:  #6b7280;
48	  --ifto-text-3:  #9ca3af;
49	  --ifto-divider: #e5e7eb;
50	  --ifto-accent:  #000000;
51	  --ifto-accent-text: #ffffff;
52	  --ifto-gray-1: #333333;
53	  --ifto-gray-4: #bdbdbd;
54	  --ifto-gray-5: #e0e0e0;
55	  --ifto-gray-6: #f2f2f2;
56	  --ifto-bg: #ffffff;
57	}
58	
59	.theme-dark .ifto-container,
60	body.theme-dark .ifto-container {
61	  --ifto-card-bg: #1c1c1c;
62	  --ifto-text:    #f5f5f5;
63	  --ifto-text-2:  #9ca3af;
64	  --ifto-text-3:  #6b7280;
65	  --ifto-divider: #2a2a2a;
66	  --ifto-accent:  #ffffff;
67	  --ifto-accent-text: #000000;
68	
69	  --ifto-shadow: 0 1px 3px rgba(0,0,0,.3), 0 4px 12px rgba(0,0,0,.4);
70	  --ifto-shadow-strong: 0 4px 16px rgba(0,0,0,.5);
71	
72	  --ifto-gray-1: #e0e0e0;
73	  --ifto-gray-4: #666666;
74	  --ifto-gray-5: #444444;
75	  --ifto-gray-6: #2a2a2a;
76	  --ifto-bg: #1e1e1e;
77	}
78	
79	.ifto-page {
80	  max-width: 1440px;
81	  margin: 0 auto;
82	  background: var(--ifto-bg);
83	  font-family: var(--ifto-font);
84	  color: var(--ifto-gray-1);
85	  min-height: 100vh;
86	}
87	
88	/* ====== Header ====== */
89	.ifto-header {
90	  position: sticky;
91	  top: 0;
92	  z-index: 100;
93	  background: var(--ifto-bg);
94	  border-bottom: 1px solid var(--ifto-gray-6);
95	}
96	
97	.ifto-nav {
98	  display: flex;
99	  align-items: center;
100	  justify-content: space-between;
101	  gap: 10px;
102	  height: 102px;
103	  padding: 0 clamp(20px, 6vw, 130px);
104	}
105	
106	.ifto-nav-items {
107	  display: flex;
108	  align-items: center;
109	  gap: clamp(6px, 1.2vw, 20px);
110	  flex-wrap: wrap;
111	  justify-content: flex-end;
112	}
113	
114	.ifto-logo {
115	  flex-shrink: 0;
116	}
117	
118	.ifto-nav-item {
119	  font-size: 12px;
120	  font-weight: 400;
121	  letter-spacing: 2.4px;
122	  text-transform: uppercase;
123	  color: var(--ifto-gray-1);
124	  text-decoration: none;
125	  padding: 4px 0;
126	  position: relative;
127	  cursor: pointer;
128	  transition: opacity 0.2s;
129	}
130	
131	.ifto-nav-item:hover { opacity: 0.7; }
132	
133	.ifto-nav-item.active::after {
134	  content: ''; position: absolute;
135	  bottom: -2px; left: 0; right: 0;
136	  height: 1px; background: var(--ifto-gray-1);
137	}
138	
139	.ifto-nav-item.active::before {
140	  content: ''; position: absolute;
141	  top: -2px; left: 0; right: 0;
142	  height: 1px; background: var(--ifto-gray-1);
143	}
144	
145	/* ====== Section ====== */
146	.ifto-section {
147	  padding: 0 var(--ifto-section-x);
148	  margin-bottom: 60px;
149	  position: relative;
150	}
151	
152	.ifto-section-title {
153	  font-size: 28px;
154	  font-weight: 600;
155	  letter-spacing: 4px;
156	  margin: 0 0 20px 0;
157	  color: var(--ifto-gray-1);
158	}
159	
160	/* ====== Hero ====== */
161	.ifto-hero {
162	  display: flex;
163	  gap: 40px;
164	  min-height: 600px;
165	  position: relative;
166	  padding-top: 70px;
167	  margin-bottom: 80px;
168	}
169	
170	.ifto-hero-bg {
171	  position: absolute;
172	  left: 0;
173	  top: 200px;
174	  font-size: 80px;
175	  color: var(--ifto-gray-4);
176	  opacity: 0.3;
177	  pointer-events: none;
178	  line-height: 1;
179	}
180	
181	.ifto-hero-content {
182	  flex: 1;
183	  position: relative;
184	  z-index: 1;
185	  padding-top: 200px;
186	}
187	
188	.ifto-hero-title {
189	  font-size: 24px;
190	  letter-spacing: 4.8px;
191	  color: var(--ifto-gray-1);
192	  margin: 0;
193	  display: flex;
194	  align-items: baseline;
195	  gap: 12px;
196	}
197	
198	.ifto-hero-subtitle {
199	  font-size: 15px;
200	  letter-spacing: 2px;
201	  text-transform: uppercase;
202	  opacity: 0.6;
203	}
204	
205	.ifto-hero-brand {
206	  font-size: 42px;
207	  font-weight: 700;
208	  color: var(--ifto-gray-1);
209	  margin: 8px 0 0 0;
210	}
211	
212	/* Shortcuts */
213	.ifto-shortcuts {
214	  display: grid;
215	  grid-template-columns: repeat(4, 115px);
216	  gap: 24px;
217	  margin: 30px 0;
218	}
219	
220	.ifto-shortcut-btn {
221	  display: flex;
222	  flex-direction: column;
223	  align-items: center;
224	  justify-content: center;
225	  gap: 10px;
226	  width: 115px;
227	  height: 53px;
228	  border: none;
229	  border-radius: 8px;
230	  background: var(--ifto-gray-6);
231	  cursor: pointer;
232	  transition: all 0.2s;
233	  font-family: var(--ifto-font);
234	}
235	
236	.ifto-shortcut-btn:hover {
237	  filter: brightness(0.95);
238	  transform: translateY(-1px);
239	}
