241	.ifto-shortcut-icon { font-size: 18px; font-weight: 300; line-height: 1; }
242	.ifto-shortcut-label { font-size: 12px; color: var(--ifto-gray-1); letter-spacing: 1px; }
243	
244	/* Hero Nav */
245	.ifto-hero-nav {
246	  display: flex;
247	  gap: 24px;
248	  margin-top: 40px;
249	}
250	
251	.ifto-hero-nav-btn {
252	  width: 53px; height: 53px;
253	  border: 1px solid var(--ifto-gray-5);
254	  border-radius: 8px;
255	  background: var(--ifto-bg);
256	  cursor: pointer;
257	  font-size: 16px;
258	  display: flex;
259	  align-items: center;
260	  justify-content: center;
261	  transition: all 0.2s;
262	  color: var(--ifto-gray-1);
263	}
264	
265	.ifto-hero-nav-btn:hover { background: var(--ifto-gray-6); }
266	
267	/* Widget Card */
268	.ifto-widget-card {
269	  width: 350px;
270	  padding: 20px;
271	  border-radius: 10px;
272	  background: var(--ifto-bg);
273	  border: 1px solid var(--ifto-gray-6);
