275	
276	.ifto-widget-title { font-size: 16px; font-weight: 600; margin: 0 0 10px 0; }
277	.ifto-widget-desc { font-size: 13px; color: var(--ifto-gray-4); line-height: 1.6; }
278	
279	/* Hero Image */
280	.ifto-hero-image {
281	  flex: 1;
282	  min-height: 400px;
283	  background: var(--ifto-gray-5);
284	  border-radius: 10px;
285	  display: flex;
286	  align-items: center;
287	  justify-content: center;
288	  margin-top: 17px;
289	  position: relative;
290	}
291	
292	/* ====== Tabs ====== */
293	.ifto-section-tabs {
294	  display: flex;
295	  align-items: center;
296	  gap: 16px;
297	  margin-bottom: 16px;
298	}
299	
300	.ifto-tab {
301	  font-size: 12px;
302	  letter-spacing: 2px;
303	  color: var(--ifto-gray-4);
304	  cursor: pointer;
