306	  position: relative;
307	  transition: color 0.2s;
308	}
309	
310	.ifto-tab.active { color: var(--ifto-gray-1); }
311	
312	.ifto-tab.active::after {
313	  content: ''; position: absolute;
314	  bottom: -3px; left: 0; right: 0;
315	  height: 1px; background: var(--ifto-gray-1);
316	}
317	
318	.ifto-back-home {
319	  margin-left: auto;
320	  font-size: 12px;
321	  letter-spacing: 2px;
