341	  width: 200px; height: 100px;
342	  background: var(--ifto-bg);
343	  border-radius: 8px;
344	  padding: 12px;
345	  display: flex;
346	  flex-direction: column;
347	  justify-content: space-between;
348	  cursor: pointer;
