355	.ifto-card-title { font-size: 12px; font-weight: 500; }
356	.ifto-card-date { font-size: 11px; color: var(--ifto-gray-4); }
357	
358	.ifto-card-add {
359	  display: flex;
360	  flex-direction: column;
361	  align-items: center;
362	  justify-content: center;
363	  gap: 10px;
