537	
538	/* ====== Notes ====== */
539	.ifto-note-layout {
540	  display: flex;
541	  gap: 14px;
542	}
543	
544	.ifto-note-sidebar {
545	  width: 350px;
546	  display: flex;
547	  flex-direction: column;
