631	
632	/* ====== Responsive ====== */
633	@media (max-width: 1200px) {
634	  .ifto-hero { min-height: clamp(450px, 55vw, 700px); }
635	  .ifto-hero-content { padding-top: 120px; }
636	  .ifto-shortcuts { gap: 16px; }
637	}
638	
639	@media (max-width: 900px) {
640	  .ifto-section { --ifto-section-x: 20px; }
641	  .ifto-nav { flex-wrap: wrap; padding: 0 clamp(12px, 3vw, 20px); height: auto; min-height: 60px; gap: 8px; }
642	  .ifto-nav-items { gap: 8px; }
643	  .ifto-hero { flex-direction: column; min-height: auto; }
644	  .ifto-hero-content { padding-top: 60px; }
645	  .ifto-hero-image { min-height: 250px; }
646	  .ifto-shortcuts { grid-template-columns: repeat(2, 115px); }
647	  .ifto-todo-layout { flex-direction: column; }
648	  .ifto-project-columns { flex-direction: column; }
649	  .ifto-note-layout { flex-direction: column; }
650	  .ifto-note-sidebar { width: 100%; }
651	  .ifto-card { width: 160px; }
652	}
653	
654	@media (max-width: 480px) {
655	  .ifto-nav { flex-wrap: wrap; justify-content: center; min-height: auto; padding: 8px 12px; }
656	  .ifto-nav-items { flex: 0 0 100%; justify-content: center; flex-wrap: wrap; }
657	  .ifto-hero-image { min-height: 160px; }
658	  .ifto-shortcuts { grid-template-columns: repeat(2, 1fr); }
659	  .ifto-card { width: 100%; }
660	}
661	
662	/* =============================================================
663	   Border-radius override (controlled by plugin setting)
664	   Sliders value 0-16 maps to px, set via --ifto-radius CSS var
665	   on documentElement by __IFTO_applyRadius bridge.
666	   !important needed to beat inline border-radius styles in home.js
